"""Private runtime configuration for the repository development CLI.

This module is deliberately outside :mod:`pdf_craft`: library callers pass
configuration objects explicitly and never load a repository ``.env``.
"""

import os
import json
import subprocess
from dataclasses import asdict
from pathlib import Path
from typing import Any, cast

from pdf_craft import (
    DeepSeekOCR2LocalConfig,
    DeepSeekOCR2VendorConfig,
    DeepSeekOCRLocalConfig,
    DeepSeekOCRVendorConfig,
    LLM,
    OCRConfig,
    OCRMode,
    UnlimitedOCRLocalConfig,
    UnlimitedOCRVendorConfig,
)


def load_project_env(project_root: Path) -> Path:
    """Load the worktree-private ``.env`` used by the development CLI."""
    path = project_root / ".env"
    if not path.is_file():
        raise SystemExit(f"Missing {path}; copy .env.template and configure it first")
    load_env(path)
    return path


def load_env(path: Path) -> None:
    """Load simple KEY=VALUE entries without overriding the process environment."""
    if not path.exists():
        return
    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        name, value = line.split("=", 1)
        os.environ.setdefault(name.strip(), value.strip().strip("\"'"))


def create_ocr_config_from_env(mode: OCRMode | None = None) -> OCRConfig:
    """Create an explicit pdf-craft OCR config from ``PDF_CRAFT_*`` settings."""
    mode = mode or cast(OCRMode, _str("PDF_CRAFT_OCR_MODE", default="deepseek-ocr-local"))
    if mode == "deepseek-ocr-local":
        return DeepSeekOCRLocalConfig(
            models_cache_path=_backend_str(
                "PDF_CRAFT_DEEPSEEK_OCR_LOCAL_MODELS_CACHE_PATH",
                "PDF_CRAFT_DEEPSEEK_MODELS_CACHE_PATH",
                default="models-cache",
            ),
            local_only=_backend_bool(
                "PDF_CRAFT_DEEPSEEK_OCR_LOCAL_ONLY",
                "PDF_CRAFT_DEEPSEEK_LOCAL_ONLY",
                default=True,
            ),
            enable_devices_numbers=_optional_ints(
                "PDF_CRAFT_DEEPSEEK_OCR_LOCAL_ENABLE_DEVICES_NUMBERS"
            ),
        )
    if mode == "deepseek-ocr2-local":
        return DeepSeekOCR2LocalConfig(
            models_cache_path=_backend_str(
                "PDF_CRAFT_DEEPSEEK_OCR2_LOCAL_MODELS_CACHE_PATH",
                "PDF_CRAFT_DEEPSEEK_MODELS_CACHE_PATH",
                default="models-cache",
            ),
            local_only=_backend_bool(
                "PDF_CRAFT_DEEPSEEK_OCR2_LOCAL_ONLY",
                "PDF_CRAFT_DEEPSEEK_LOCAL_ONLY",
                default=True,
            ),
            enable_devices_numbers=_optional_ints(
                "PDF_CRAFT_DEEPSEEK_OCR2_LOCAL_ENABLE_DEVICES_NUMBERS"
            ),
        )
    if mode == "unlimited-ocr-local":
        return UnlimitedOCRLocalConfig(
            models_cache_path=_backend_str(
                "PDF_CRAFT_UNLIMITED_OCR_LOCAL_MODELS_CACHE_PATH",
                "PDF_CRAFT_UNLIMITED_MODELS_CACHE_PATH",
                default="models-cache",
            ),
            local_only=_backend_bool(
                "PDF_CRAFT_UNLIMITED_OCR_LOCAL_ONLY",
                "PDF_CRAFT_UNLIMITED_LOCAL_ONLY",
                default=True,
            ),
            enable_devices_numbers=_optional_ints(
                "PDF_CRAFT_UNLIMITED_OCR_LOCAL_ENABLE_DEVICES_NUMBERS"
            ),
        )
    if mode == "deepseek-ocr-vendor":
        return DeepSeekOCRVendorConfig(
            base_url=_required("PDF_CRAFT_DEEPSEEK_OCR_BASE_URL"),
            api_key=_required("PDF_CRAFT_DEEPSEEK_OCR_API_KEY"),
            model=_required("PDF_CRAFT_DEEPSEEK_OCR_MODEL"),
            temperature=_optional_float("PDF_CRAFT_DEEPSEEK_OCR_TEMPERATURE"),
            top_p=_optional_float("PDF_CRAFT_DEEPSEEK_OCR_TOP_P"),
            max_tokens=_int("PDF_CRAFT_DEEPSEEK_OCR_MAX_TOKENS", default=8000),
            timeout_seconds=_int("PDF_CRAFT_DEEPSEEK_OCR_TIMEOUT_SECONDS", default=180),
        )
    if mode == "deepseek-ocr2-vendor":
        return DeepSeekOCR2VendorConfig(
            base_url=_required("PDF_CRAFT_DEEPSEEK_OCR2_BASE_URL"),
            api_key=_required("PDF_CRAFT_DEEPSEEK_OCR2_API_KEY"),
            model=_required("PDF_CRAFT_DEEPSEEK_OCR2_MODEL"),
            temperature=_optional_float("PDF_CRAFT_DEEPSEEK_OCR2_TEMPERATURE"),
            top_p=_optional_float("PDF_CRAFT_DEEPSEEK_OCR2_TOP_P"),
            max_tokens=_int("PDF_CRAFT_DEEPSEEK_OCR2_MAX_TOKENS", default=8000),
            timeout_seconds=_int("PDF_CRAFT_DEEPSEEK_OCR2_TIMEOUT_SECONDS", default=180),
        )
    if mode == "unlimited-ocr-vendor":
        return UnlimitedOCRVendorConfig(
            ak=_required("PDF_CRAFT_UNLIMITED_OCR_ACCESS_KEY"),
            sk=_required("PDF_CRAFT_UNLIMITED_OCR_SECRET_KEY"),
            base_url=_str("PDF_CRAFT_UNLIMITED_OCR_BASE_URL", default="https://aip.baidubce.com"),
            poll_interval_seconds=_float("PDF_CRAFT_UNLIMITED_OCR_POLL_INTERVAL_SECONDS", default=2.0),
            timeout_seconds=_int("PDF_CRAFT_UNLIMITED_OCR_TIMEOUT_SECONDS", default=180),
        )
    raise SystemExit(f"Unsupported PDF_CRAFT_OCR_MODE: {mode}")


def ocr_mode_from_env() -> OCRMode:
    """Return the selected OCR mode without initializing its backend."""
    return cast(OCRMode, _str("PDF_CRAFT_OCR_MODE", default="deepseek-ocr-local"))


def ocr_values_from_env(mode: OCRMode) -> dict[str, object]:
    """Return the explicit values used by a smoke run without exposing secrets."""
    return asdict(create_ocr_config_from_env(mode))


def create_llm_from_env(profile: str, *, cache_path: Path, log_dir_path: Path) -> LLM:
    """Create a named local-tool LLM profile without leaking credentials to disk."""
    return LLM(
        **cast(Any, llm_values_from_env(profile, cache_path=cache_path, log_dir_path=log_dir_path))
    )


def llm_values_from_env(profile: str, *, cache_path: Path, log_dir_path: Path) -> dict[str, Any]:
    """Return LLM constructor values for a named local-tool profile."""
    normalized = profile.upper().replace("-", "_")
    selected = _str(f"PDF_CRAFT_LLM_{normalized}_PROFILE", default=profile)
    if selected != profile:
        return llm_values_from_env(selected, cache_path=cache_path, log_dir_path=log_dir_path)
    prefix = f"PDF_CRAFT_LLM_{normalized}"
    if _str(f"{prefix}_PROVIDER", default="openai") == "oomol":
        values = _oomol_llm_values()
    else:
        values = {
            "key": _required(f"{prefix}_API_KEY"),
            "url": _required(f"{prefix}_BASE_URL"),
            "model": _required(f"{prefix}_MODEL"),
        }
    return values | {
        "token_encoding": _str(f"{prefix}_TOKEN_ENCODING", default="o200k_base"),
        "timeout": _float(f"{prefix}_TIMEOUT_SECONDS", default=180.0),
        "temperature": _optional_float(f"{prefix}_TEMPERATURE"),
        "top_p": _optional_float(f"{prefix}_TOP_P"),
        "retry_times": _int(f"{prefix}_RETRY_TIMES", default=3),
        "cache_path": str(cache_path),
        "log_dir_path": str(log_dir_path),
    }


def _oomol_llm_values() -> dict[str, str]:
    """Obtain ephemeral OOMOL credentials without persisting or logging them."""
    try:
        result = subprocess.run(
            ["oo", "llm", "config", "--json"], check=True, capture_output=True, text=True
        )
        config = json.loads(result.stdout)
    except (OSError, subprocess.CalledProcessError, json.JSONDecodeError) as error:
        raise SystemExit("Unable to load OOMOL LLM configuration; run `oo auth login`") from error
    required = {key: config.get(key) for key in ("apiKey", "baseUrl", "model")}
    if not all(isinstance(value, str) and value for value in required.values()):
        raise SystemExit("OOMOL LLM configuration is incomplete; run `oo auth login`")
    return {
        "key": cast(str, required["apiKey"]),
        "url": cast(str, required["baseUrl"]),
        "model": cast(str, required["model"]),
    }


def _str(name: str, default: str | None = None) -> str:
    value = os.environ.get(name, "").strip()
    return value or (default or "")


def _backend_str(name: str, legacy_name: str, default: str) -> str:
    """Read a backend-specific setting, retaining the pre-six-backend alias."""
    return _str(name) or _str(legacy_name, default)


def _required(name: str) -> str:
    value = _str(name)
    if not value:
        raise SystemExit(f"Missing required environment variable: {name}")
    return value


def _bool(name: str, default: bool) -> bool:
    value = _str(name)
    if not value:
        return default
    if value.lower() in {"1", "true", "yes", "on"}:
        return True
    if value.lower() in {"0", "false", "no", "off"}:
        return False
    raise SystemExit(f"{name} must be a boolean")


def _backend_bool(name: str, legacy_name: str, default: bool) -> bool:
    """Read a backend-specific boolean, retaining the pre-six-backend alias."""
    if _str(name):
        return _bool(name, default)
    return _bool(legacy_name, default)


def _optional_ints(name: str) -> tuple[int, ...] | None:
    value = _str(name)
    if not value:
        return None
    try:
        values = tuple(int(item.strip()) for item in value.split(","))
    except ValueError as error:
        raise SystemExit(f"{name} must be comma-separated integers") from error
    if not values:
        return None
    return values


def _int(name: str, default: int) -> int:
    try:
        return int(_str(name, str(default)))
    except ValueError as error:
        raise SystemExit(f"{name} must be an integer") from error


def _float(name: str, default: float) -> float:
    try:
        return float(_str(name, str(default)))
    except ValueError as error:
        raise SystemExit(f"{name} must be a number") from error


def _optional_float(name: str) -> float | None:
    value = _str(name)
    return float(value) if value else None

"""Output-directory allocation for repository-local CLI runs."""

import re
from datetime import datetime
from pathlib import Path


DEFAULT_OUTPUT_ROOT = Path("pdf-craft-output")


def create_run_directory(root: Path, label: str, *, now: datetime | None = None) -> Path:
    """Create a date- and sequence-suffixed directory below *root*."""
    day = (now or datetime.now().astimezone()).strftime("%Y%m%d")
    root.mkdir(parents=True, exist_ok=True)
    sequence = _next_sequence(root, day)
    while True:
        path = root / f"{label}-{day}-{sequence:03d}"
        try:
            path.mkdir()
        except FileExistsError:
            sequence += 1
        else:
            return path


def _next_sequence(root: Path, day: str) -> int:
    pattern = re.compile(rf".*-{re.escape(day)}-(\d+)$")
    sequences = (
        int(match.group(1))
        for path in root.iterdir()
        if path.is_dir() and (match := pattern.fullmatch(path.name))
    )
    return max(sequences, default=0) + 1
